  "sql": "WITH _base AS (\n  SELECT\n    DATE_TRUNC('MONTH', orders.order_date) AS \"orders.order_date\"\n  FROM orders AS orders\n  WHERE\n    (\n      orders.order_date >= CAST('2025-01-01' AS DATE)\n      AND orders.order_date < CAST('2026-01-01' AS DATE)\n    )\n  GROUP BY\n    DATE_TRUNC('MONTH', orders.order_date)\n), _cm_orders__customer_id_count_distinct_window_90d AS (\n  SELECT\n    _base.\"orders.order_date\",\n    COUNT(DISTINCT _src._w_value) AS \"orders.c\"\n  FROM (\n    SELECT\n      DATE_TRUNC('MONTH', orders.order_date) AS \"orders.order_date\"\n    FROM orders AS orders\n    WHERE\n      (\n        orders.order_date >= CAST('2025-01-01' AS DATE)\n        AND orders.order_date < CAST('2026-01-01' AS DATE)\n      )\n    GROUP BY\n      DATE_TRUNC('MONTH', orders.order_date)\n  ) AS _base\n  LEFT JOIN (\n    SELECT\n      orders.order_date AS _w_time,\n      orders.customer_id AS _w_value\n    FROM orders AS orders\n  ) AS _src\n    ON _src._w_time >= CAST(CAST(_base.\"orders.order_date\" + INTERVAL 1 MONTH AS DATE) - INTERVAL 90 DAY AS DATE)\n    AND _src._w_time < CAST(_base.\"orders.order_date\" + INTERVAL 1 MONTH AS DATE)\n  GROUP BY\n    _base.\"orders.order_date\"\n)\nSELECT\n  _base.\"orders.order_date\",\n  COALESCE(_cm_orders__customer_id_count_distinct_window_90d.\"orders.c\", 0) AS \"orders.c\"\nFROM _base\nLEFT JOIN _cm_orders__customer_id_count_distinct_window_90d\n  ON _base.\"orders.order_date\" IS NOT DISTINCT FROM _cm_orders__customer_id_count_distinct_window_90d.\"orders.order_date\"\nORDER BY\n  _base.\"orders.order_date\" ASC\nLIMIT 101"
